class S3Client:
    def __init__(self):
        self._client = None
        self._credentials_file = "/home/ec2-user/.aws/credentials"
        self._IS_IN_STUDIO = False

    def _create_client(self):
        if self._IS_IN_STUDIO:
            try:
                credentials = botocore.credentials.InstanceMetadataProvider().load()
            except NoCredentialsError:
                credentials = None
        else:
            if os.path.isfile(self._credentials_file):
                credentials = botocore.credentials.SharedCredentialsProvider(filename=self._credentials_file).load()
            else:
                credentials = None

        if credentials:
            self._client = boto3.client(
                "s3",
                aws_access_key_id=credentials.access_key,
                aws_secret_access_key=credentials.secret_key,
                aws_session_token=credentials.token,
                config=botocore.config.Config(retries={"max_attempts": 1000, "mode": "adaptive"}),
            )

    def client(self) -> Any:
        if self._client is None:
            self._create_client()
        return self._client
